/* Common Flexbox patterns */

/* 1. Centered content (both axes) */
.center-content {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

/* 2. Navigation bar with logo left, links right */
.navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
}

.navbar__links {
  display: flex;
  gap: 1.5rem;
  list-style: none;
}

/* 3. Card row that wraps responsively */
.card-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.card {
  flex: 1 1 300px; /* Grow, shrink, min 300px before wrapping */
  max-width: 400px;
}

/* 4. Sticky footer layout */
.page-layout {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.page-layout__content {
  flex: 1; /* Grows to push footer down */
}

/* 5. Equal-height columns */
.columns {
  display: flex;
  gap: 2rem;
}

.columns__item {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.columns__item-footer {
  margin-top: auto; /* Push to bottom of column */
}

/* CSS Grid layout patterns */

/* 1. Classic holy grail layout with named areas */
.page-layout {
  display: grid;
  grid-template-areas:
    "header  header  header"
    "sidebar content aside"
    "footer  footer  footer";
  grid-template-columns: 250px 1fr 200px;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
  gap: 1rem;
}

.page-header  { grid-area: header; }
.page-sidebar { grid-area: sidebar; }
.page-content { grid-area: content; }
.page-aside   { grid-area: aside; }
.page-footer  { grid-area: footer; }

/* 2. Responsive auto-fit card grid */
.dashboard-widgets {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
  padding: 1.5rem;
}

/* 3. Spanning items for featured content */
.featured-card {
  grid-column: span 2;
  grid-row: span 2;
}

/* 4. Dense packing for masonry-like layouts */
.image-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  grid-auto-rows: 200px;
  grid-auto-flow: dense;
  gap: 0.5rem;
}

.image-gallery__item--tall {
  grid-row: span 2;
}

.image-gallery__item--wide {
  grid-column: span 2;
}

/* 5. Responsive layout without media queries */
.responsive-layout {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 400px), 1fr));
  gap: 2rem;
}

/* Mobile-first responsive design system */

/* Base: Mobile (< 480px) — no media query needed */
.container {
  width: 100%;
  padding-inline: 1rem;
  margin-inline: auto;
}

.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

/* Fluid typography */
:root {
  --font-size-base: clamp(1rem, 0.9rem + 0.5vw, 1.125rem);
  --font-size-h1: clamp(1.75rem, 1.5rem + 1.5vw, 3rem);
  --font-size-h2: clamp(1.375rem, 1.2rem + 1vw, 2.25rem);
  --spacing-unit: clamp(0.75rem, 0.5rem + 1vw, 1.5rem);
}

body {
  font-size: var(--font-size-base);
  line-height: 1.6;
}

/* Tablet breakpoint */
@media (min-width: 768px) {
  .container {
    padding-inline: 2rem;
    max-width: 720px;
  }

  .grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
  }

  .sidebar {
    display: block; /* Hidden on mobile */
    width: 250px;
  }
}

/* Desktop breakpoint */
@media (min-width: 1024px) {
  .container {
    max-width: 960px;
    padding-inline: 2rem;
  }

  .grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
  }
}

/* Large desktop */
@media (min-width: 1440px) {
  .container {
    max-width: 1200px;
  }
}

/* Accessibility: reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  :root {
    --color-bg: #1a1a2e;
    --color-text: #e0e0e0;
    --color-primary: #6366f1;
  }
}

/* Touch target sizing */
.btn,
.nav-link,
.form-input {
  min-height: 44px;
  min-width: 44px;
  padding: 0.75rem 1rem;
}

/* Design token system with CSS custom properties */

/* Global tokens — design system level */
:root {
  /* Color palette */
  --color-primary-50: #eef2ff;
  --color-primary-100: #e0e7ff;
  --color-primary-500: #6366f1;
  --color-primary-600: #4f46e5;
  --color-primary-700: #4338ca;
  --color-primary-900: #312e81;

  /* Semantic tokens */
  --color-bg: #ffffff;
  --color-text: #1f2937;
  --color-text-muted: #6b7280;
  --color-border: #e5e7eb;
  --color-surface: #f9fafb;
  --color-accent: var(--color-primary-500);
  --color-error: #ef4444;
  --color-success: #10b981;

  /* Spacing scale (4px base) */
  --space-base: 0.25rem;
  --space-1: calc(var(--space-base) * 1);   /* 4px */
  --space-2: calc(var(--space-base) * 2);   /* 8px */
  --space-3: calc(var(--space-base) * 3);   /* 12px */
  --space-4: calc(var(--space-base) * 4);   /* 16px */
  --space-6: calc(var(--space-base) * 6);   /* 24px */
  --space-8: calc(var(--space-base) * 8);   /* 32px */

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 1rem;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
  --transition-fast: 150ms ease;
  --transition-normal: 300ms ease;
}

/* Dark theme override */
[data-theme="dark"] {
  --color-bg: #1a1a2e;
  --color-text: #e5e7eb;
  --color-text-muted: #9ca3af;
  --color-border: #374151;
  --color-surface: #1f2937;
  --color-accent: #818cf8;
}

/* Component-scoped tokens */
.card {
  --card-padding: var(--space-6);
  --card-radius: var(--radius-md);
  --card-bg: var(--color-surface);
  --card-border: var(--color-border);

  padding: var(--card-padding);
  border-radius: var(--card-radius);
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-fast);
}

.card:hover {
  box-shadow: var(--shadow-md);
}

/* Variant through property override */
.card--featured {
  --card-bg: var(--color-primary-50);
  --card-border: var(--color-primary-200);
}

